    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int q = (int) in.nval;
        long[] ids = new long[q], starts = new long[q], ends = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken(); ids[i] = (long) in.nval;
            in.nextToken(); starts[i] = (long) in.nval;
            in.nextToken(); ends[i] = (long) in.nval;
        }
        boolean[] res = processRequests(ids, starts, ends);
        StringBuilder sb = new StringBuilder();
        for (boolean x : res) sb.append(x ? "true" : "false").append('\n');
        System.out.print(sb);
    }
}
